css:
.comarquage-theme-signature.comarquage {
    --cq-blue: #145c73;
    --cq-blue-dark: #12242c;
    --cq-cyan: #e94f37;
    --cq-soft: #f5f1ea;
    --cq-line: #d8d0c3;
    --cq-shadow: 0 20px 60px rgba(18,36,44,.14);
}
.comarquage-theme-signature .comarquage-hero {
    background: linear-gradient(120deg,#12242c 0%,#145c73 52%,#f5f1ea 52%,#fffaf2 100%);
    border-bottom: 6px solid #e94f37;
}
.comarquage-theme-signature .comarquage-topic-grid {
    grid-template-columns: repeat(4,minmax(0,1fr));
}
.comarquage-theme-signature .comarquage-topic {
    border: 0;
    box-shadow: 0 12px 30px rgba(18,36,44,.08);
    min-height: 10.5rem;
}
.comarquage-theme-signature .comarquage-topic-icon {
    background: #12242c;
    color: #fff;
    border-radius: 999px;
}
.comarquage-theme-signature .comarquage-featured {
    grid-template-columns: 1.2fr 1fr 1fr;
}
.comarquage-theme-signature .comarquage-featured article {
    border: 0;
    border-top: 5px solid var(--cq-cyan);
}
@media (max-width: 980px) {
    .comarquage-theme-signature .comarquage-topic-grid,
    .comarquage-theme-signature .comarquage-featured {
        grid-template-columns: repeat(2,minmax(0,1fr));
    }
}
@media (max-width: 620px) {
    .comarquage-theme-signature .comarquage-topic-grid,
    .comarquage-theme-signature .comarquage-featured {
        grid-template-columns: 1fr;
    }
}
